    main()

"""Credential and configuration persistence."""

from __future__ import annotations

import json
import sys
from pathlib import Path

from .exceptions import ConfigError

DEFAULT_CONFIG_DIR = Path.home() / ".discogs-sync"
DEFAULT_CONFIG_FILE = DEFAULT_CONFIG_DIR / "config.json"


def get_config_path() -> Path:
    return DEFAULT_CONFIG_FILE


def load_config() -> dict:
    """Load configuration from disk. Returns empty dict if file doesn't exist."""
    path = get_config_path()
    if not path.exists():
        return {}
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError) as e:
        raise ConfigError(f"Failed to read config file {path}: {e}") from e


def save_config(config: dict) -> None:
    """Save configuration to disk."""
    path = get_config_path()
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(config, indent=2), encoding="utf-8")
        # Restrict permissions to owner-only on non-Windows platforms
        if sys.platform != "win32":
            path.chmod(0o600)
    except OSError as e:
        raise ConfigError(f"Failed to write config file {path}: {e}") from e


def get_cache_ttl() -> int:
    """Return the cache TTL in seconds.

    Reads ``cache_ttl_hours`` from the config file. If not set, defaults to
    24 hours (86400 seconds). The value may be a float (e.g. 0.5 for 30 minutes).
    """
    config = load_config()
    hours = config.get("cache_ttl_hours", 24)
    try:
        return int(float(hours) * 3600)
    except (TypeError, ValueError):
        return 86400


def get_auth_mode() -> str:
    """Return the configured auth mode ('token' or 'oauth'). Defaults to 'token'."""
    config = load_config()
    return config.get("auth_mode", "oauth" if config.get("access_token") else "token")


def get_tokens() -> dict | None:
    """Return stored credentials, or None if not configured.

    Supports both personal access token and OAuth modes.
    Legacy configs (no auth_mode key) are treated as OAuth.
    """
    config = load_config()
    auth_mode = config.get("auth_mode")

    # Token mode
    if auth_mode == "token":
        user_token = config.get("user_token")
        if user_token:
            return {
                "auth_mode": "token",
                "user_token": user_token,
                "username": config.get("username"),
            }
        return None

    # OAuth mode (explicit or legacy config without auth_mode)
    token = config.get("access_token")
    secret = config.get("access_token_secret")
    if token and secret:
        return {
            "auth_mode": "oauth",
            "access_token": token,
            "access_token_secret": secret,
            "consumer_key": config.get("consumer_key", ""),
            "consumer_secret": config.get("consumer_secret", ""),
            "username": config.get("username"),
        }
    return None


def save_tokens(
    consumer_key: str,
    consumer_secret: str,
    access_token: str,
    access_token_secret: str,
    username: str | None = None,
) -> None:
    """Store OAuth tokens to config file."""
    config = load_config()
    config.update(
        {
            "auth_mode": "oauth",
            "consumer_key": consumer_key,
            "consumer_secret": consumer_secret,
            "access_token": access_token,
            "access_token_secret": access_token_secret,
            "username": username,
        }
    )
    save_config(config)


def save_user_token(user_token: str, username: str | None = None) -> None:
    """Store a personal access token to config file."""
    config = load_config()
    config.update(
        {
            "auth_mode": "token",
            "user_token": user_token,
            "username": username,
        }
    )
    save_config(config)


def clear_tokens() -> None:
    """Remove all stored credentials (both token and OAuth)."""
    config = load_config()
    for key in [
        "auth_mode", "user_token",
        "access_token", "access_token_secret",
        "consumer_key", "consumer_secret",
        "username",
    ]:
        config.pop(key, None)
    save_config(config)

"""Custom exceptions for discogs-sync."""


class DiscogsSyncError(Exception):
    """Base exception for discogs-sync."""


class AuthenticationError(DiscogsSyncError):
    """Authentication failed or tokens are invalid."""


class ConfigError(DiscogsSyncError):
    """Configuration file is missing or invalid."""


class ParseError(DiscogsSyncError):
    """Input file parsing failed."""

    def __init__(self, message: str, errors: list[dict] | None = None):
        super().__init__(message)
        self.errors = errors or []


class SearchError(DiscogsSyncError):
    """Release search failed."""


class SyncError(DiscogsSyncError):
    """Sync operation failed."""


class RateLimitError(DiscogsSyncError):
    """Rate limit exceeded and retries exhausted."""


class NetworkError(DiscogsSyncError):
    """Network request failed after retries."""

"""Marketplace stats lookup via master versions."""

from __future__ import annotations

from typing import TYPE_CHECKING

from .exceptions import SyncError
from .models import InputRecord, MarketplaceResult
from .output import print_verbose
from .parsers import extract_artist_from_data
from .rate_limiter import get_rate_limiter
from .search import (
    _api_call_with_retry,
    resolve_to_release_id,
    search_release,
)

if TYPE_CHECKING:
    import discogs_client

DEFAULT_MAX_VERSIONS = 25


def _extract_lowest_price(stats) -> float | None:
    """Extract lowest_price as a float from marketplace stats.

    Handles the various forms the Discogs API may return:
    - MarketplaceStats object with a Price object (has .value)
    - Price object wrapping a raw numeric .data (no .value)
    - Plain dict
    - Raw number
    """
    lp = None
    if hasattr(stats, "lowest_price"):
        lp = stats.lowest_price
    elif isinstance(stats, dict):
        lp = stats.get("lowest_price")

    if lp is None:
        return None

    if hasattr(lp, "value"):
        return float(lp.value)
    if isinstance(lp, dict):
        return float(lp.get("value", 0))
    if isinstance(lp, (int, float)):
        return float(lp)
    if hasattr(lp, "data") and isinstance(lp.data, (int, float)):
        return float(lp.data)
    return float(str(lp))

# Module-level flag to skip price_suggestions after a "seller settings" 404.
# Reset at the start of each search_marketplace call.
_skip_price_suggestions = False


def _extract_price_suggestions(release, limiter, verbose: bool = False) -> dict[str, float] | None:
    """Fetch price suggestions by condition grade for a release.

    Returns dict like {"Mint (M)": 50.0, "Near Mint (NM or M-)": 40.0, ...}
    or None on failure. Keys match the Discogs API condition grade names.
    """
    # Map from PriceSuggestions property names to API key names
    _GRADE_ATTRS = {
        "mint": "Mint (M)",
        "near_mint": "Near Mint (NM or M-)",
        "very_good_plus": "Very Good Plus (VG+)",
        "very_good": "Very Good (VG)",
        "good_plus": "Good Plus (G+)",
        "good": "Good (G)",
        "fair": "Fair (F)",
        "poor": "Poor (P)",
    }

    global _skip_price_suggestions

    release_id = getattr(release, "id", None) or (release.data.get("id") if hasattr(release, "data") else "?")

    if _skip_price_suggestions:
        if verbose:
            print_verbose(f"  price_suggestions for release {release_id}: skipped (seller settings not configured)")
        return None

    try:
        suggestions = _api_call_with_retry(lambda: release.price_suggestions, limiter, verbose=verbose, description=f"release({release_id}).price_suggestions")
        if not suggestions:
            if verbose:
                print_verbose(f"  price_suggestions for release {release_id}: returned empty/None")
            return None

        if verbose:
            print_verbose(f"  price_suggestions for release {release_id}: type={type(suggestions).__name__}")

        result: dict[str, float] = {}

        # PriceSuggestions object: access via named properties
        for attr, grade_key in _GRADE_ATTRS.items():
            price_obj = getattr(suggestions, attr, None)
            if price_obj is not None:
                if hasattr(price_obj, "value") and price_obj.value is not None:
                    result[grade_key] = float(price_obj.value)
                elif isinstance(price_obj, (int, float)):
                    result[grade_key] = float(price_obj)

        # Fallback: if it's a plain dict (e.g. from mocks)
        if not result and isinstance(suggestions, dict):
            for grade, price_obj in suggestions.items():
                if isinstance(price_obj, dict):
                    val = price_obj.get("value")
                    if val is not None:
                        result[grade] = float(val)
                elif hasattr(price_obj, "value") and price_obj.value is not None:
                    result[grade] = float(price_obj.value)
                elif isinstance(price_obj, (int, float)):
                    result[grade] = float(price_obj)

        if verbose:
            if result:
                print_verbose(f"  price_suggestions for release {release_id}: {len(result)} grades extracted")
            else:
                print_verbose(f"  price_suggestions for release {release_id}: no grades could be extracted from {type(suggestions).__name__}")

        return result if result else None
    except Exception as e:
        if verbose:
            print_verbose(f"  price_suggestions for release {release_id}: error - {e}")
        if "seller settings" in str(e).lower():
            _skip_price_suggestions = True
            if verbose:
                print_verbose("  Disabling price_suggestions for remaining releases (seller settings not configured)")
        return None


def search_marketplace(
    client: discogs_client.Client,
    master_id: int | None = None,
    release_id: int | None = None,
    artist: str | None = None,
    album: str | None = None,
    format: str | None = None,
    country: str | None = None,
    min_price: float | None = None,
    max_price: float | None = None,
    currency: str = "USD",
    max_versions: int = DEFAULT_MAX_VERSIONS,
    threshold: float = 0.7,
    details: bool = False,
    verbose: bool = False,
) -> list[MarketplaceResult]:
    """Search marketplace stats for a single item.

    Resolves to master_id, fetches versions, gets stats for each.
    """
    global _skip_price_suggestions
    _skip_price_suggestions = False
    limiter = get_rate_limiter()

    # If release_id explicitly provided (without master_id), show only that release
    if release_id and not master_id:
        return _get_stats_for_release(client, release_id, currency, min_price, max_price, limiter, details=details, verbose=verbose)

    # Resolve to master_id
    if not master_id:
        if artist and album:
            record = InputRecord(artist=artist, album=album, format=format)
            result = search_release(client, record, threshold=threshold)
            if not result.matched:
                raise SyncError(f"No match found for {artist} - {album}")
            master_id = result.master_id
            if not master_id and result.release_id:
                release = _api_call_with_retry(lambda: client.release(result.release_id), limiter, verbose=verbose, description=f"release({result.release_id})")
                _api_call_with_retry(lambda: release.refresh(), limiter, verbose=verbose, description=f"release({result.release_id}).refresh()")
                data = release.data if hasattr(release, "data") else {}
                if verbose:
                    print_verbose(f"Fetched release {result.release_id}: keys={list(data.keys())}")
                master_id = data.get("master_id")
            if not master_id:
                # Fall back to single release stats
                rid = resolve_to_release_id(client, result)
                if rid:
                    return _get_stats_for_release(client, rid, currency, min_price, max_price, limiter, details=details, verbose=verbose)
                raise SyncError(f"Could not resolve master or release for {artist} - {album}")
        else:
            raise SyncError("Must provide --master-id, --release-id, or both --artist and --album")

    # Fetch master versions
    if verbose:
        print_verbose(f"Fetching versions for master_id={master_id}")
    master = _api_call_with_retry(lambda: client.master(master_id), limiter, verbose=verbose, description=f"master({master_id})")
    if verbose:
        print_verbose(f"Fetching versions list for master_id={master_id}")
    versions = _api_call_with_retry(lambda: master.versions, limiter, verbose=verbose, description=f"master({master_id}).versions")
    if verbose:
        # Try to get total count from the versions object
        total_versions = None
        if hasattr(versions, 'pages'):
            total_versions = getattr(versions, 'pages', None)
        if hasattr(versions, 'count'):
            total_versions = getattr(versions, 'count', None)
        print_verbose(f"Versions object: type={type(versions).__name__}, total={total_versions}, max_to_check={max_versions}")

    results: list[MarketplaceResult] = []
    count = 0
    page_num = 1

    while count < max_versions:
        if verbose:
            print_verbose(f"Fetching versions page {page_num} (matched {count}/{max_versions} so far)")
        try:
            page = _api_call_with_retry(lambda p=page_num: versions.page(p), limiter, verbose=verbose, description=f"versions.page({page_num})")
            if not page:
                if verbose:
                    print_verbose(f"Page {page_num} returned empty, stopping")
                break
        except Exception as e:
            if verbose:
                print_verbose(f"Page {page_num} fetch failed: {e}, stopping")
            break

        if verbose:
            page_len = len(page) if hasattr(page, '__len__') else '?'
            print_verbose(f"Page {page_num} returned {page_len} versions")

        for version in page:
            if count >= max_versions:
                break

            data = version.data if hasattr(version, "data") else {}
            version_id = data.get("id") or getattr(version, "id", None)
            if not version_id:
                continue

            # Filter by format if specified
            if format:
                version_formats = data.get("major_formats", [])
                if not version_formats:
                    fmt_str = data.get("format", "")
                    version_formats = [fmt_str] if fmt_str else []
                if not any(format.lower() in str(f).lower() for f in version_formats):
                    if verbose:
                        print_verbose(f"  Skipping version {version_id}: formats {version_formats} don't match '{format}'")
                    continue

            # Filter by country if specified
            if country:
                version_country = data.get("country", "")
                if not version_country or country.lower() != version_country.lower():
                    if verbose:
                        print_verbose(f"  Skipping version {version_id}: country '{version_country}' doesn't match '{country}'")
                    continue

            # Get marketplace stats
            try:
                if verbose:
                    print_verbose(f"  Fetching release {version_id}...")
                release = _api_call_with_retry(lambda vid=version_id: client.release(vid), limiter, verbose=verbose, description=f"release({version_id})")
                # Force full data load — client.release() creates a lazy object
                _api_call_with_retry(lambda r=release: r.refresh(), limiter, verbose=verbose, description=f"release({version_id}).refresh()")
                release_data = release.data if hasattr(release, "data") else {}
                if verbose:
                    print_verbose(f"  Release {version_id}: data keys={list(release_data.keys())}, "
                                  f"artist={'artists' in release_data}, country={release_data.get('country', '<missing>')}")
                stats = _api_call_with_retry(lambda r=release: r.marketplace_stats, limiter, verbose=verbose, description=f"release({version_id}).marketplace_stats")

                num_for_sale = 0
                if hasattr(stats, "num_for_sale"):
                    num_for_sale = stats.num_for_sale or 0
                elif isinstance(stats, dict):
                    num_for_sale = stats.get("num_for_sale", 0)

                lowest_price = _extract_lowest_price(stats)

                # Apply price filters
                if min_price is not None and (lowest_price is None or lowest_price < min_price):
                    continue
                if max_price is not None and (lowest_price is None or lowest_price > max_price):
                    continue

                # Parse artist and title
                artist_name = extract_artist_from_data(release_data)
                album_name = release_data.get("title", data.get("title", ""))
                if not artist_name and " - " in album_name:
                    artist_name, album_name = album_name.split(" - ", 1)

                # Parse format
                fmt = None
                formats = release_data.get("formats", [])
                if formats and isinstance(formats, list):
                    fmt = formats[0].get("name", "") if isinstance(formats[0], dict) else str(formats[0])
                if not fmt:
                    fmt = data.get("format", "")

                # Fetch price suggestions if details requested
                price_suggestions = None
                if details:
                    price_suggestions = _extract_price_suggestions(release, limiter, verbose=verbose)

                results.append(MarketplaceResult(
                    master_id=master_id,
                    release_id=version_id,
                    title=album_name,
                    artist=artist_name,
                    format=fmt,
                    country=release_data.get("country", data.get("country")),
                    year=release_data.get("year", data.get("year")),
                    num_for_sale=num_for_sale,
                    lowest_price=lowest_price,
                    currency=currency,
                    price_suggestions=price_suggestions,
                ))

                count += 1

            except Exception as e:
                if verbose:
                    print_verbose(f"  Release {version_id}: error fetching stats - {e}")
                continue

        page_num += 1

    if verbose:
        print_verbose(f"Version scan complete: {count} versions matched across {page_num - 1} pages")

    # Sort by lowest_price ascending (None values at end)
    results.sort(key=lambda r: (r.lowest_price is None, r.lowest_price or 0))

    return results


def fetch_price_suggestions_for_results(
    client: discogs_client.Client,
    results: list[MarketplaceResult],
    verbose: bool = False,
) -> dict[int, dict | None]:
    """Fetch price suggestions for an already-resolved list of marketplace results.

    Used when base results are available from cache but ``price_suggestions``
    have not been fetched yet (i.e. the details cache is cold).

    Args:
        client: Authenticated Discogs client.
        results: List of :class:`MarketplaceResult` whose ``release_id`` values
            are used to look up price suggestions.
        verbose: If ``True``, print progress messages.

    Returns:
        Mapping of ``release_id`` → price-suggestions dict (or ``None`` on
        failure).  Release IDs with no ``release_id`` value are skipped.
    """
    global _skip_price_suggestions
    _skip_price_suggestions = False
    limiter = get_rate_limiter()
    suggestions: dict[int, dict | None] = {}
    for result in results:
        if result.release_id is None:
            continue
        try:
            release = _api_call_with_retry(
                lambda rid=result.release_id: client.release(rid),
                limiter, verbose=verbose, description=f"release({result.release_id})",
            )
            _api_call_with_retry(
                lambda r=release: r.refresh(),
                limiter, verbose=verbose, description=f"release({result.release_id}).refresh()",
            )
            suggestions[result.release_id] = _extract_price_suggestions(release, limiter, verbose=verbose)
        except Exception:
            suggestions[result.release_id] = None
    return suggestions


def search_marketplace_batch(
    client: discogs_client.Client,
    records: list[InputRecord],
    format: str | None = None,
    country: str | None = None,
    min_price: float | None = None,
    max_price: float | None = None,
    currency: str = "USD",
    max_versions: int = DEFAULT_MAX_VERSIONS,
    threshold: float = 0.7,
    details: bool = False,
    verbose: bool = False,
) -> tuple[list[MarketplaceResult], list[dict]]:
    """Search marketplace for a batch of records.

    Returns (results, errors) where errors is a list of error dicts.
    """
    all_results: list[MarketplaceResult] = []
    errors: list[dict] = []

    for record in records:
        try:
            if verbose:
                print_verbose(f"Searching marketplace: {record.artist} - {record.album}")
            results = search_marketplace(
                client,
                artist=record.artist,
                album=record.album,
                format=format or record.format,
                country=country,
                min_price=min_price,
                max_price=max_price,
                currency=currency,
                max_versions=max_versions,
                threshold=threshold,
                details=details,
                verbose=verbose,
            )
            all_results.extend(results)
        except Exception as e:
            errors.append({
                "artist": record.artist,
                "album": record.album,
                "error": str(e),
            })

    return all_results, errors


def _get_stats_for_release(
    client,
    release_id: int,
    currency: str,
    min_price: float | None,
    max_price: float | None,
    limiter,
    details: bool = False,
    verbose: bool = False,
) -> list[MarketplaceResult]:
    """Get marketplace stats for a single release."""
    release = _api_call_with_retry(lambda: client.release(release_id), limiter, verbose=verbose, description=f"release({release_id})")
    # Force full data load — client.release() creates a lazy object
    _api_call_with_retry(lambda: release.refresh(), limiter, verbose=verbose, description=f"release({release_id}).refresh()")
    data = release.data if hasattr(release, "data") else {}
    if verbose:
        print_verbose(f"Fetched release {release_id}: keys={list(data.keys())}, "
                      f"artist={'artists' in data}, country={data.get('country', '<missing>')}")
    stats = _api_call_with_retry(lambda: release.marketplace_stats, limiter, verbose=verbose, description=f"release({release_id}).marketplace_stats")

    num_for_sale = 0
    if hasattr(stats, "num_for_sale"):
        num_for_sale = stats.num_for_sale or 0
    elif isinstance(stats, dict):
        num_for_sale = stats.get("num_for_sale", 0)

    lowest_price = _extract_lowest_price(stats)

    if min_price is not None and (lowest_price is None or lowest_price < min_price):
        return []
    if max_price is not None and (lowest_price is None or lowest_price > max_price):
        return []

    artist_name = extract_artist_from_data(data)
    album_name = data.get("title", "")
    if not artist_name and " - " in album_name:
        artist_name, album_name = album_name.split(" - ", 1)

    fmt = None
    format_details = None
    formats = data.get("formats", [])
    if formats and isinstance(formats, list):
        fmt = formats[0].get("name", "") if isinstance(formats[0], dict) else str(formats[0])
        if isinstance(formats[0], dict):
            descriptions = formats[0].get("descriptions", [])
            if descriptions:
                format_details = ", ".join(descriptions)

    # Extract label and catalog number
    label = None
    catno = None
    labels = data.get("labels", [])
    if labels and isinstance(labels, list) and isinstance(labels[0], dict):
        label = labels[0].get("name")
        catno = labels[0].get("catno")

    # Extract community stats
    community_have = None
    community_want = None
    community = data.get("community", {})
    if isinstance(community, dict):
        community_have = community.get("have")
        community_want = community.get("want")

    price_suggestions = None
    if details:
        price_suggestions = _extract_price_suggestions(release, limiter, verbose=verbose)

    return [MarketplaceResult(
        master_id=data.get("master_id"),
        release_id=release_id,
        title=album_name,
        artist=artist_name,
        format=fmt,
        country=data.get("country"),
        year=data.get("year"),
        num_for_sale=num_for_sale,
        lowest_price=lowest_price,
        currency=currency,
        price_suggestions=price_suggestions,
        label=label,
        catno=catno,
        format_details=format_details,
        community_have=community_have,
        community_want=community_want,
    )]

"""CSV and JSON input file parsing and validation."""

from __future__ import annotations

import csv
import json
from pathlib import Path

from .exceptions import ParseError
from .models import InputRecord

# Format normalization map
FORMAT_SYNONYMS: dict[str, str] = {
    "lp": "Vinyl",
    "record": "Vinyl",
    '12"': "Vinyl",
    "12 inch": "Vinyl",
    "vinyl": "Vinyl",
    "compact disc": "CD",
    "cd": "CD",
    "tape": "Cassette",
    "mc": "Cassette",
    "cassette": "Cassette",
}

REQUIRED_FIELDS = {"artist", "album"}
VALID_FIELDS = {"artist", "album", "format", "year", "notes"}


def normalize_format(fmt: str | None) -> str | None:
    """Normalize format synonyms to canonical names."""
    if not fmt:
        return None
    normalized = FORMAT_SYNONYMS.get(fmt.strip().lower())
    if normalized:
        return normalized
    # Return original if not a known synonym (e.g., "Vinyl", "CD" already canonical)
    return fmt.strip()


def extract_artist_from_data(data: dict) -> str:
    """Extract artist name from Discogs API release data.

    The API provides artists as a list of dicts with 'name' and 'join' keys.
    Artist names may include disambiguation suffixes like '(4)' which are stripped.
    """
    import re

    artists = data.get("artists", [])
    if not artists or not isinstance(artists, list):
        return ""
    parts = []
    for i, a in enumerate(artists):
        if not isinstance(a, dict):
            continue
        name = a.get("anv") or a.get("name", "")
        # Strip Discogs disambiguation suffix, e.g. "John Williams (4)" -> "John Williams"
        name = re.sub(r"\s*\(\d+\)$", "", name)
        parts.append(name)
        if i < len(artists) - 1:
            join = a.get("join", "").strip()
            if join and join != ",":
                parts.append(f" {join} ")
            elif join == ",":
                parts.append(", ")
            else:
                parts.append(", ")
    return "".join(parts)


def parse_file(filepath: str | Path) -> list[InputRecord]:
    """Parse an input file (CSV or JSON) and return validated records.

    Auto-detects format by file extension.
    """
    path = Path(filepath)
    if not path.exists():
        raise ParseError(f"File not found: {path}")

    ext = path.suffix.lower()
    if ext == ".csv":
        return parse_csv(path)
    elif ext == ".json":
        return parse_json(path)
    else:
        raise ParseError(f"Unsupported file format: {ext}. Use .csv or .json")


def parse_csv(path: Path) -> list[InputRecord]:
    """Parse a CSV file into InputRecords."""
    errors: list[dict] = []
    records: list[InputRecord] = []

    try:
        text = path.read_text(encoding="utf-8")
    except OSError as e:
        raise ParseError(f"Failed to read file: {e}") from e

    reader = csv.DictReader(text.splitlines())

    if reader.fieldnames is None:
        raise ParseError("CSV file is empty or has no header row")

    # Normalize header names to lowercase
    field_map = {f.strip().lower(): f for f in reader.fieldnames}

    # Check required fields
    missing = REQUIRED_FIELDS - set(field_map.keys())
    if missing:
        raise ParseError(f"CSV missing required columns: {', '.join(sorted(missing))}")

    for line_num, row in enumerate(reader, start=2):  # line 1 is header
        # Normalize keys
        normalized = {k.strip().lower(): (v.strip() if v else "") for k, v in row.items()}
        record, error = _validate_row(normalized, line_num)
        if error:
            errors.append(error)
        else:
            records.append(record)

    total = len(records) + len(errors)
    if total == 0:
        raise ParseError("CSV file contains no data rows")

    if errors and len(errors) > total * 0.5:
        raise ParseError(
            f"Too many invalid rows ({len(errors)}/{total}). Aborting.",
            errors=errors,
        )

    if errors:
        # Report errors but continue with valid records
        from .output import print_warning

        for e in errors:
            print_warning(f"Line {e['line']}: {e['message']}")

    return records


def parse_json(path: Path) -> list[InputRecord]:
    """Parse a JSON file into InputRecords."""
    errors: list[dict] = []
    records: list[InputRecord] = []

    try:
        text = path.read_text(encoding="utf-8")
    except OSError as e:
        raise ParseError(f"Failed to read file: {e}") from e

    try:
        data = json.loads(text)
    except json.JSONDecodeError as e:
        raise ParseError(f"Invalid JSON: {e}") from e

    if not isinstance(data, list):
        raise ParseError("JSON input must be an array of objects")

    if not data:
        raise ParseError("JSON file contains no records")

    for idx, item in enumerate(data):
        if not isinstance(item, dict):
            errors.append({"line": idx + 1, "message": "Item is not an object"})
            continue

        normalized = {k.strip().lower(): (str(v).strip() if v is not None else "") for k, v in item.items()}
        record, error = _validate_row(normalized, idx + 1)
        if error:
            errors.append(error)
        else:
            records.append(record)

    total = len(records) + len(errors)
    if errors and len(errors) > total * 0.5:
        raise ParseError(
            f"Too many invalid records ({len(errors)}/{total}). Aborting.",
            errors=errors,
        )

    if errors:
        from .output import print_warning

        for e in errors:
            print_warning(f"Record {e['line']}: {e['message']}")

    return records


def _validate_row(row: dict[str, str], line_number: int) -> tuple[InputRecord | None, dict | None]:
    """Validate a single row and return (record, error)."""
    artist = row.get("artist", "").strip()
    album = row.get("album", "").strip()

    if not artist:
        return None, {"line": line_number, "message": "Missing required field: artist"}
    if not album:
        return None, {"line": line_number, "message": "Missing required field: album"}

    fmt = normalize_format(row.get("format"))

    year = None
    year_str = row.get("year", "").strip()
    if year_str:
        try:
            year = int(year_str)
            if year < 1900 or year > 2030:
                return None, {"line": line_number, "message": f"Year out of range: {year}"}
        except ValueError:
            return None, {"line": line_number, "message": f"Invalid year: {year_str}"}

    notes = row.get("notes", "").strip() or None

    return InputRecord(
        artist=artist,
        album=album,
        format=fmt,
        year=year,
        notes=notes,
        line_number=line_number,
    ), None

"""Multi-pass release matching: map (artist, album) to Discogs release_id/master_id."""

from __future__ import annotations

import difflib
import time
from typing import TYPE_CHECKING

from .exceptions import NetworkError, SearchError
from .models import InputRecord, SearchResult
from .output import print_info
from .rate_limiter import get_rate_limiter

if TYPE_CHECKING:
    import discogs_client


DEFAULT_THRESHOLD = 0.7
MAX_RETRIES = 3
RETRY_DELAY = 5.0


def search_release(
    client: discogs_client.Client,
    record: InputRecord,
    threshold: float = DEFAULT_THRESHOLD,
) -> SearchResult:
    """Search Discogs for a release matching the input record.

    Uses multi-pass search:
    1. Structured search with all fields
    2. Relaxed search (drop format/year)
    3. Free text search

    Returns the best matching SearchResult.
    """
    limiter = get_rate_limiter()

    # Pass 1: Structured search
    result = _structured_search(client, record, limiter, threshold)
    if result and result.matched:
        return result

    # Pass 2: Relaxed search (drop format and year)
    result = _relaxed_search(client, record, limiter, threshold)
    if result and result.matched:
        return result

    # Pass 3: Free text search
    result = _freetext_search(client, record, limiter, threshold)
    if result and result.matched:
        return result

    return SearchResult(
        input_record=record,
        matched=False,
        error=f"No match found above threshold {threshold}",
    )


def resolve_to_release_id(
    client: discogs_client.Client,
    search_result: SearchResult,
    preferred_format: str | None = None,
) -> int | None:
    """Resolve a SearchResult to a specific release_id.

    If master_id found + format specified: find matching version.
    If master_id found + no format: use main_release.
    If release_id only: return it directly.
    """
    if search_result.release_id and not search_result.master_id:
        return search_result.release_id

    if not search_result.master_id:
        return search_result.release_id

    limiter = get_rate_limiter()
    master = _api_call_with_retry(lambda: client.master(search_result.master_id), limiter)

    fmt = preferred_format or search_result.input_record.format
    if fmt:
        # Try to find a version matching the format
        release_id = _find_version_by_format(client, master, fmt, limiter)
        if release_id:
            return release_id

    # Fall back to main release
    try:
        return master.main_release.id
    except Exception:
        return search_result.release_id


def resolve_master_id(
    client: discogs_client.Client,
    master_id: int,
    preferred_format: str | None = None,
) -> int:
    """Resolve a master_id to a release_id."""
    limiter = get_rate_limiter()
    master = _api_call_with_retry(lambda: client.master(master_id), limiter)

    if preferred_format:
        release_id = _find_version_by_format(client, master, preferred_format, limiter)
        if release_id:
            return release_id

    return master.main_release.id


def _structured_search(
    client: discogs_client.Client,
    record: InputRecord,
    limiter,
    threshold: float,
) -> SearchResult | None:
    """Pass 1: Structured search with all available fields."""
    kwargs: dict = {
        "release_title": record.album,
        "artist": record.artist,
        "type": "master",
    }
    if record.format:
        kwargs["format"] = record.format
    if record.year:
        kwargs["year"] = str(record.year)

    results = _api_call_with_retry(lambda: client.search(**kwargs), limiter)
    return _score_results(results, record, threshold)


def _relaxed_search(
    client: discogs_client.Client,
    record: InputRecord,
    limiter,
    threshold: float,
) -> SearchResult | None:
    """Pass 2: Drop format and year constraints."""
    results = _api_call_with_retry(
        lambda: client.search(
            release_title=record.album,
            artist=record.artist,
            type="master",
        ),
        limiter,
    )
    return _score_results(results, record, threshold)


def _freetext_search(
    client: discogs_client.Client,
    record: InputRecord,
    limiter,
    threshold: float,
) -> SearchResult | None:
    """Pass 3: Free text search as last resort."""
    query = f"{record.artist} {record.album}"
    results = _api_call_with_retry(
        lambda: client.search(query, type="release"),
        limiter,
    )
    return _score_results(results, record, threshold)


def _score_results(results, record: InputRecord, threshold: float) -> SearchResult | None:
    """Score search results and return the best match above threshold."""
    if not results:
        return None

    best_score = 0.0
    best_result = None

    # Only check first page of results (typically 50 items)
    try:
        page = results.page(1)
    except Exception:
        return None

    for item in page:
        score = _compute_score(item, record)
        if score > best_score:
            best_score = score
            best_result = item

    if best_result is None or best_score < threshold:
        return None

    # Extract fields from result
    try:
        artist_name = _get_artist_name(best_result)
        title = getattr(best_result, "title", "") or ""
        # title is often "Artist - Album", extract album part
        if " - " in title:
            title = title.split(" - ", 1)[1]

        master_id = None
        release_id = None

        # Determine IDs based on result type
        if hasattr(best_result, "data"):
            data = best_result.data
            if data.get("type") == "master":
                master_id = data.get("id") or getattr(best_result, "id", None)
            else:
                release_id = data.get("id") or getattr(best_result, "id", None)
                master_id = data.get("master_id")
        else:
            release_id = getattr(best_result, "id", None)

        year = None
        if hasattr(best_result, "data"):
            year = best_result.data.get("year")
        if not year:
            year = getattr(best_result, "year", None)
        if year:
            try:
                year = int(year)
            except (ValueError, TypeError):
                year = None

        fmt = None
        if hasattr(best_result, "data"):
            formats = best_result.data.get("format", [])
            if formats:
                fmt = formats[0] if isinstance(formats, list) else str(formats)

        country = None
        if hasattr(best_result, "data"):
            country = best_result.data.get("country")

        return SearchResult(
            input_record=record,
            release_id=release_id,
            master_id=master_id,
            title=title,
            artist=artist_name,
            year=year,
            format=fmt,
            country=country,
            score=best_score,
            matched=True,
        )
    except Exception as e:
        return SearchResult(
            input_record=record,
            matched=False,
            error=f"Error processing search result: {e}",
        )


def _compute_score(result, record: InputRecord) -> float:
    """Compute a match score (0.0-1.0) for a search result against an input record."""
    score = 0.0

    # Get result artist and title
    result_artist = _get_artist_name(result)
    result_title = getattr(result, "title", "") or ""
    if " - " in result_title:
        result_title = result_title.split(" - ", 1)[1]

    # Artist similarity (40%)
    artist_sim = _similarity(record.artist, result_artist)
    score += 0.4 * artist_sim

    # Album title similarity (40%)
    title_sim = _similarity(record.album, result_title)
    score += 0.4 * title_sim

    # Year match (10%)
    if record.year:
        result_year = None
        if hasattr(result, "data"):
            result_year = result.data.get("year")
        if not result_year:
            result_year = getattr(result, "year", None)
        if result_year:
            try:
                result_year = int(result_year)
                if result_year == record.year:
                    score += 0.1
            except (ValueError, TypeError):
                pass

    # Format match (10%)
    if record.format:
        result_formats = []
        if hasattr(result, "data"):
            fmt_data = result.data.get("format", [])
            if isinstance(fmt_data, list):
                result_formats = [str(f).lower() for f in fmt_data]
            elif fmt_data:
                result_formats = [str(fmt_data).lower()]
        if any(record.format.lower() in f for f in result_formats):
            score += 0.1

    return score


def _get_artist_name(result) -> str:
    """Extract artist name from a search result."""
    if hasattr(result, "data"):
        # Try title field which is "Artist - Album"
        title = result.data.get("title", "")
        if " - " in title:
            return title.split(" - ", 1)[0]
    # Fallback
    title = getattr(result, "title", "") or ""
    if " - " in title:
        return title.split(" - ", 1)[0]
    return ""


def _similarity(a: str, b: str) -> float:
    """Compute normalized string similarity using SequenceMatcher."""
    if not a or not b:
        return 0.0
    return difflib.SequenceMatcher(None, a.lower().strip(), b.lower().strip()).ratio()


def _find_version_by_format(client, master, format_name: str, limiter) -> int | None:
    """Find a version of a master release matching the given format."""
    try:
        versions = _api_call_with_retry(lambda: master.versions, limiter)
        # Check first page of versions
        page = versions.page(1)
        for version in page:
            data = version.data if hasattr(version, "data") else {}
            formats = data.get("major_formats", [])
            if not formats:
                formats = data.get("format", "")
                if isinstance(formats, str):
                    formats = [formats]
            for fmt in formats:
                if format_name.lower() in str(fmt).lower():
                    return data.get("id") or getattr(version, "id", None)
    except Exception:
        pass
    return None


def _api_call_with_retry(call, limiter, retries: int = MAX_RETRIES, verbose: bool = False, description: str = ""):
    """Execute an API call with rate limiting and retries."""
    last_error = None
    desc = f" ({description})" if description else ""
    for attempt in range(retries):
        wait_info = limiter.wait_if_needed(verbose=verbose, description=description)
        try:
            t0 = time.monotonic()
            result = call()
            elapsed = time.monotonic() - t0
            # Try to extract headers for rate limit tracking
            if hasattr(result, "_response") and hasattr(result._response, "headers"):
                limiter.update_from_headers(dict(result._response.headers))
            if verbose and (elapsed > 2.0 or description):
                remaining = limiter.remaining
                from .output import print_verbose
                print_verbose(f"API call{desc}: {elapsed:.1f}s (remaining={remaining})")
            return result
        except Exception as e:
            last_error = e
            if verbose:
                from .output import print_verbose
                print_verbose(f"API call{desc} attempt {attempt + 1}/{retries} failed: {e}")
            if attempt < retries - 1:
                if verbose:
                    from .output import print_verbose
                    print_verbose(f"  Retrying in {RETRY_DELAY}s...")
                time.sleep(RETRY_DELAY)
    raise NetworkError(f"API call failed after {retries} retries: {last_error}") from last_error

"""Collection sync operations."""

from __future__ import annotations

from typing import TYPE_CHECKING

from .exceptions import SyncError
from .models import (
    CollectionItem,
    InputRecord,
    SearchResult,
    SyncAction,
    SyncActionType,
    SyncReport,
)
from .output import print_verbose
from .parsers import extract_artist_from_data
from .rate_limiter import get_rate_limiter
from .search import (
    _api_call_with_retry,
    _similarity,
    resolve_master_id,
    resolve_to_release_id,
    search_release,
)

if TYPE_CHECKING:
    import discogs_client

DEFAULT_ADD_FOLDER = 1   # "Uncategorized"
DEFAULT_READ_FOLDER = 0  # "All"
FUZZY_MATCH_THRESHOLD = 0.85


def sync_collection(
    client: discogs_client.Client,
    records: list[InputRecord],
    folder_id: int = DEFAULT_ADD_FOLDER,
    remove_extras: bool = False,
    dry_run: bool = False,
    threshold: float = 0.7,
    verbose: bool = False,
) -> SyncReport:
    """Sync a list of input records to the user's collection."""
    report = SyncReport(total_input=len(records))
    limiter = get_rate_limiter()

    if verbose:
        print_verbose(f"Starting collection sync: {len(records)} input records, folder_id={folder_id}, threshold={threshold}, dry_run={dry_run}, remove_extras={remove_extras}")

    # Step 1: Resolve all records
    resolved: list[tuple[InputRecord, SearchResult]] = []
    for i, record in enumerate(records, 1):
        if verbose:
            print_verbose(f"[{i}/{len(records)}] Searching: {record.artist} - {record.album}" + (f" [{record.format}]" if record.format else ""))
        try:
            result = search_release(client, record, threshold=threshold)
            if result.matched:
                if verbose:
                    print_verbose(f"  Matched: {result.artist} - {result.title} (score={result.score:.2f}, master_id={result.master_id}, release_id={result.release_id})")
                release_id = resolve_to_release_id(client, result)
                if release_id:
                    if verbose and release_id != result.release_id:
                        print_verbose(f"  Resolved to release_id={release_id}")
                    result.release_id = release_id
                    resolved.append((record, result))
                else:
                    if verbose:
                        print_verbose(f"  Failed to resolve to release ID")
                    report.add_action(SyncAction(
                        action=SyncActionType.ERROR,
                        input_record=record,
                        error="Could not resolve to release ID",
                    ))
            else:
                if verbose:
                    print_verbose(f"  No match: {result.error or 'below threshold'}")
                report.add_action(SyncAction(
                    action=SyncActionType.ERROR,
                    input_record=record,
                    error=result.error or "No match found",
                ))
        except Exception as e:
            if verbose:
                print_verbose(f"  Error: {e}")
            report.add_action(SyncAction(
                action=SyncActionType.ERROR,
                input_record=record,
                error=str(e),
            ))

    if verbose:
        print_verbose(f"Resolved {len(resolved)}/{len(records)} records")

    # Step 2: Fetch current collection
    if verbose:
        print_verbose("Fetching current collection...")
    current, current_masters, current_items = _get_collection_release_ids(client, DEFAULT_READ_FOLDER, limiter)
    if verbose:
        print_verbose(f"Current collection has {len(current)} unique releases, {len(current_masters)} unique masters")

    # Step 3: Diff
    target_ids = set()
    for record, result in resolved:
        release_id = result.release_id
        target_ids.add(release_id)

        if release_id in current:
            if verbose:
                print_verbose(f"  SKIP (release_id match): {result.artist} - {result.title} (release_id={release_id})")
            report.add_action(SyncAction(
                action=SyncActionType.SKIP,
                input_record=record,
                release_id=release_id,
                master_id=result.master_id,
                title=result.title,
                artist=result.artist,
                reason="Already in collection",
            ))
        elif result.master_id and result.master_id in current_masters:
            if verbose:
                print_verbose(f"  SKIP (master_id match): {result.artist} - {result.title} (master_id={result.master_id})")
            report.add_action(SyncAction(
                action=SyncActionType.SKIP,
                input_record=record,
                release_id=release_id,
                master_id=result.master_id,
                title=result.title,
                artist=result.artist,
                reason="Already in collection",
            ))
        elif _fuzzy_match_items(result.artist, result.title, current_items, verbose):
            report.add_action(SyncAction(
                action=SyncActionType.SKIP,
                input_record=record,
                release_id=release_id,
                master_id=result.master_id,
                title=result.title,
                artist=result.artist,
                reason="Already in collection (fuzzy match)",
            ))
        else:
            if verbose:
                print_verbose(f"  ADD: release_id={release_id} not in collection, master_id={result.master_id} not in masters, no fuzzy match")
            if not dry_run:
                try:
                    if verbose:
                        print_verbose(f"  ADD: {result.artist} - {result.title} (release_id={release_id}) to folder {folder_id}")
                    _add_to_collection(client, release_id, folder_id, limiter)
                except Exception as e:
                    if verbose:
                        print_verbose(f"  ERROR adding release_id={release_id}: {e}")
                    report.add_action(SyncAction(
                        action=SyncActionType.ERROR,
                        input_record=record,
                        release_id=release_id,
                        error=f"Failed to add: {e}",
                    ))
                    continue
            elif verbose:
                print_verbose(f"  ADD (dry run): {result.artist} - {result.title} (release_id={release_id})")

            report.add_action(SyncAction(
                action=SyncActionType.ADD,
                input_record=record,
                release_id=release_id,
                master_id=result.master_id,
                title=result.title,
                artist=result.artist,
                reason="Dry run" if dry_run else None,
            ))

    # Step 4: Remove extras
    if remove_extras:
        extras = set(current.keys()) - target_ids
        if verbose:
            print_verbose(f"Checking extras: {len(extras)} releases in collection not in input")
        for release_id in extras:
            instance_ids = current[release_id]
            for instance_id in instance_ids:
                if not dry_run:
                    try:
                        if verbose:
                            print_verbose(f"  REMOVE: release_id={release_id}, instance_id={instance_id}")
                        _remove_from_collection(client, release_id, instance_id, DEFAULT_READ_FOLDER, limiter)
                    except Exception as e:
                        if verbose:
                            print_verbose(f"  ERROR removing release_id={release_id} instance={instance_id}: {e}")
                        report.add_action(SyncAction(
                            action=SyncActionType.ERROR,
                            release_id=release_id,
                            error=f"Failed to remove instance {instance_id}: {e}",
                        ))
                        continue
                elif verbose:
                    print_verbose(f"  REMOVE (dry run): release_id={release_id}, instance_id={instance_id}")

                report.add_action(SyncAction(
                    action=SyncActionType.REMOVE,
                    release_id=release_id,
                    reason="Not in input file" + (" (dry run)" if dry_run else ""),
                ))

    return report


def add_to_collection(
    client: discogs_client.Client,
    release_id: int | None = None,
    master_id: int | None = None,
    artist: str | None = None,
    album: str | None = None,
    format: str | None = None,
    folder_id: int = DEFAULT_ADD_FOLDER,
    allow_duplicate: bool = False,
    threshold: float = 0.7,
) -> SyncAction:
    """Add a single item to the collection."""
    limiter = get_rate_limiter()

    release_id = _resolve_item(
        client, release_id=release_id, master_id=master_id,
        artist=artist, album=album, format=format, threshold=threshold,
    )

    # Check for duplicates unless allowed
    if not allow_duplicate:
        current, current_masters, current_items = _get_collection_release_ids(client, DEFAULT_READ_FOLDER, limiter)
        if release_id in current or (master_id and master_id in current_masters):
            return SyncAction(
                action=SyncActionType.SKIP,
                release_id=release_id,
                artist=artist,
                title=album,
                reason="Already in collection (use --allow-duplicate to add another copy)",
            )
        if artist and album and _fuzzy_match_items(artist, album, current_items):
            return SyncAction(
                action=SyncActionType.SKIP,
                release_id=release_id,
                artist=artist,
                title=album,
                reason="Already in collection (fuzzy match, use --allow-duplicate to add another copy)",
            )

    _add_to_collection(client, release_id, folder_id, limiter)

    return SyncAction(
        action=SyncActionType.ADD,
        release_id=release_id,
        artist=artist,
        title=album,
    )


def remove_from_collection(
    client: discogs_client.Client,
    release_id: int | None = None,
    artist: str | None = None,
    album: str | None = None,
    format: str | None = None,
    folder_id: int = DEFAULT_READ_FOLDER,
    threshold: float = 0.7,
) -> SyncAction:
    """Remove a single item from the collection."""
    limiter = get_rate_limiter()

    release_id = _resolve_item(
        client, release_id=release_id, artist=artist, album=album,
        format=format, threshold=threshold,
    )

    current, _, _ = _get_collection_release_ids(client, folder_id, limiter)
    if release_id not in current:
        return SyncAction(
            action=SyncActionType.SKIP,
            release_id=release_id,
            artist=artist,
            title=album,
            reason="Not in collection",
        )

    # Remove first instance
    instance_id = current[release_id][0]
    _remove_from_collection(client, release_id, instance_id, folder_id, limiter)

    return SyncAction(
        action=SyncActionType.REMOVE,
        release_id=release_id,
        artist=artist,
        title=album,
    )


def list_collection(
    client: discogs_client.Client,
    folder_id: int = DEFAULT_READ_FOLDER,
) -> list[CollectionItem]:
    """Fetch and return all collection items from a folder."""
    limiter = get_rate_limiter()
    me = _api_call_with_retry(lambda: client.identity(), limiter)
    folder = _api_call_with_retry(
        lambda: me.collection_folders[folder_id],
        limiter,
    )
    releases = _api_call_with_retry(lambda: folder.releases, limiter)

    items = []
    page_num = 1
    while True:
        try:
            page = _api_call_with_retry(lambda p=page_num: releases.page(p), limiter)
            if not page:
                break
            for item in page:
                release = item.release if hasattr(item, "release") else item
                data = release.data if hasattr(release, "data") else {}

                artist_name = extract_artist_from_data(data)
                album_name = data.get("title", "")

                fmt = None
                formats = data.get("formats", [])
                if formats and isinstance(formats, list):
                    fmt = formats[0].get("name", "") if isinstance(formats[0], dict) else str(formats[0])

                instance_id = getattr(item, "instance_id", None) or data.get("instance_id", 0)
                if hasattr(item, "data") and isinstance(item.data, dict):
                    instance_id = item.data.get("instance_id", instance_id)

                items.append(CollectionItem(
                    instance_id=instance_id,
                    release_id=data.get("id", getattr(release, "id", 0)),
                    master_id=data.get("master_id"),
                    folder_id=folder_id,
                    title=album_name,
                    artist=artist_name,
                    format=fmt,
                    year=data.get("year"),
                ))
            page_num += 1
        except Exception:
            break

    return items


def _resolve_item(
    client,
    release_id: int | None = None,
    master_id: int | None = None,
    artist: str | None = None,
    album: str | None = None,
    format: str | None = None,
    threshold: float = 0.7,
) -> int:
    """Resolve various input forms to a release_id."""
    if release_id:
        return release_id

    if master_id:
        return resolve_master_id(client, master_id, preferred_format=format)

    if not artist or not album:
        raise SyncError("Must provide --release-id, --master-id, or both --artist and --album")

    record = InputRecord(artist=artist, album=album, format=format)
    result = search_release(client, record, threshold=threshold)
    if not result.matched:
        raise SyncError(f"No match found for {record.display_name()}")

    resolved_id = resolve_to_release_id(client, result)
    if not resolved_id:
        raise SyncError(f"Could not resolve release ID for {record.display_name()}")

    return resolved_id


def _get_collection_release_ids(client, folder_id: int, limiter) -> tuple[dict[int, list[int]], set[int], list[tuple[str, str, int]]]:
    """Fetch release_id -> [instance_id] mapping, set of master_ids, and (artist, title, release_id) tuples from collection."""
    me = _api_call_with_retry(lambda: client.identity(), limiter)
    folder = _api_call_with_retry(
        lambda: me.collection_folders[folder_id],
        limiter,
    )
    releases = _api_call_with_retry(lambda: folder.releases, limiter)

    mapping: dict[int, list[int]] = {}
    master_ids: set[int] = set()
    items_info: list[tuple[str, str, int]] = []
    page_num = 1
    while True:
        try:
            page = _api_call_with_retry(lambda p=page_num: releases.page(p), limiter)
            if not page:
                break
            for item in page:
                release = item.release if hasattr(item, "release") else item
                data = release.data if hasattr(release, "data") else {}
                rid = data.get("id") or getattr(release, "id", None)
                instance_id = getattr(item, "instance_id", None) or 0
                if hasattr(item, "data") and isinstance(item.data, dict):
                    instance_id = item.data.get("instance_id", instance_id)
                if rid:
                    mapping.setdefault(rid, []).append(instance_id)
                    artist_name = extract_artist_from_data(data)
                    album_name = data.get("title", "")
                    items_info.append((artist_name, album_name, rid))
                mid = data.get("master_id")
                if mid:
                    master_ids.add(mid)
            page_num += 1
        except Exception:
            break

    return mapping, master_ids, items_info


def _fuzzy_match_items(
    artist: str | None,
    title: str | None,
    items: list[tuple[str, str, int]],
    verbose: bool = False,
) -> bool:
    """Check if artist+title fuzzy-matches any item in the list."""
    if not artist or not title:
        return False
    for item_artist, item_title, item_rid in items:
        a_sim = _similarity(artist, item_artist)
        t_sim = _similarity(title, item_title)
        if a_sim >= FUZZY_MATCH_THRESHOLD and t_sim >= FUZZY_MATCH_THRESHOLD:
            if verbose:
                print_verbose(
                    f"  SKIP (fuzzy match): '{artist} - {title}' matched '{item_artist} - {item_title}' "
                    f"(release_id={item_rid}, artist_sim={a_sim:.2f}, title_sim={t_sim:.2f})"
                )
            return True
    return False


def _add_to_collection(client, release_id: int, folder_id: int, limiter) -> None:
    """Add a release to a collection folder."""
    me = _api_call_with_retry(lambda: client.identity(), limiter)
    _api_call_with_retry(
        lambda: me.collection_folders[folder_id].add_release(release_id),
        limiter,
    )


def _remove_from_collection(client, release_id: int, instance_id: int, folder_id: int, limiter) -> None:
    """Remove a release instance from a collection folder."""
    me = _api_call_with_retry(lambda: client.identity(), limiter)
    _api_call_with_retry(
        lambda: me.collection_folders[folder_id].remove_release(release_id, instance_id),
        limiter,
    )
